// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./interfaces/IERC20.sol";
import "./interfaces/ISwapCallee.sol";
import "./interfaces/ISwapPair.sol";
import "./interfaces/ISwapRouter02.sol";

/**
 * FlashArbitrageur
 *
 * 交换流程（依赖 exchange1 的 Pair 做 Flash Swap 回调）：
 * - executeFlashArb() 触发 exchange1 pair 的 swap(data) -> 回调 swapCall()
 * - swapCall() 中：
 *   1) 用借出的 tokenBorrow 在 exchange2 做 tokenBorrow -> tokenOther
 *   2) 用 tokenOther 在 exchange1 做 tokenOther -> tokenBorrow
 *   3) 偿还 exchange1 pair 的 tokenBorrow，并把剩余 profit 转给 profitRecipient
 *
 * 说明：
 * - 为了让后端无需知道用户钱包地址，本合约会在 executeFlashArb() 时把 profitRecipient 强制覆盖为 msg.sender。
 */
contract FlashArbitrageur is ISwapCallee {
    struct ArbParams {
        address pair1; // exchange1 的 Pair（Flash Swap 触发方，且后续偿还方）
        address router1; // exchange1 的 Router（用于把 tokenOther 再换回 tokenBorrow）
        address router2; // exchange2 的 Router（用于把 tokenBorrow 换成 tokenOther）
        address tokenBorrow; // 从 pair1 借出的 token（也必须是偿还 token）
        address tokenOther; // 在 exchange2 兑换出来的另一个 token
        uint256 amountBorrow; // 期望借出的数量（用来做校验与偿还计算）
        uint256 amountOutMinSwap2; // exchange2 swap: tokenBorrow -> tokenOther 的最小输出
        uint256 amountOutMinSwap1; // exchange1 swap: tokenOther -> tokenBorrow 的最小输出
        address profitRecipient; // 初始值无所谓，会被 executeFlashArb() 覆盖为 msg.sender
        uint256 deadline; // router swap deadline
    }

    event FlashArbExecuted(
        address indexed initiator,
        address indexed pair1,
        address indexed tokenBorrow,
        uint256 borrowedAmount,
        uint256 amountOwed,
        uint256 profit
    );

    function executeFlashArb(ArbParams calldata params) external {
        require(params.pair1 != address(0), "FLASH: pair1=0");
        require(params.router1 != address(0), "FLASH: router1=0");
        require(params.router2 != address(0), "FLASH: router2=0");
        require(params.tokenBorrow != address(0), "FLASH: tokenBorrow=0");
        require(params.tokenOther != address(0), "FLASH: tokenOther=0");
        require(params.amountBorrow > 0, "FLASH: amountBorrow=0");

        // profitRecipient 强制覆盖为调用者（用户钱包），避免后端需要知道钱包地址。
        ArbParams memory p = params;
        p.profitRecipient = msg.sender;

        ISwapPair pair = ISwapPair(p.pair1);
        address token0 = pair.token0();
        address token1 = pair.token1();

        uint256 amount0Out;
        uint256 amount1Out;
        if (p.tokenBorrow == token0) {
            amount0Out = p.amountBorrow;
            amount1Out = 0;
        } else if (p.tokenBorrow == token1) {
            amount0Out = 0;
            amount1Out = p.amountBorrow;
        } else {
            revert("FLASH: tokenBorrow not in pair");
        }

        // to = address(this) 以接收 swapCall 回调。
        bytes memory data = abi.encode(p);
        pair.swap(amount0Out, amount1Out, address(this), data);
    }

    function swapCall(
        address sender,
        uint amount0,
        uint amount1,
        bytes calldata data
    ) external override {
        require(sender == address(this), "FLASH: bad sender");

        ArbParams memory params = abi.decode(data, (ArbParams));
        require(msg.sender == params.pair1, "FLASH: bad pair");

        uint256 borrowedAmount = amount0 > 0 ? amount0 : amount1;
        require(borrowedAmount == params.amountBorrow, "FLASH: bad borrowedAmount");

        // 1) exchange2: tokenBorrow -> tokenOther
        IERC20(params.tokenBorrow).approve(params.router2, borrowedAmount);
        address[] memory path2 = new address[](2);
        path2[0] = params.tokenBorrow;
        path2[1] = params.tokenOther;
        ISwapRouter02(params.router2).swapExactTokensForTokens(
            borrowedAmount,
            params.amountOutMinSwap2,
            path2,
            address(this),
            params.deadline
        );

        // 2) exchange1: tokenOther -> tokenBorrow
        uint256 tokenOtherBal = IERC20(params.tokenOther).balanceOf(address(this));
        require(tokenOtherBal > 0, "FLASH: no tokenOther");
        IERC20(params.tokenOther).approve(params.router1, tokenOtherBal);
        address[] memory path1 = new address[](2);
        path1[0] = params.tokenOther;
        path1[1] = params.tokenBorrow;
        ISwapRouter02(params.router1).swapExactTokensForTokens(
            tokenOtherBal,
            params.amountOutMinSwap1,
            path1,
            address(this),
            params.deadline
        );

        // 3) repay to exchange1 pair
        uint256 amountOwed = (params.amountBorrow * 1000) / 997 + 1;
        uint256 finalBorrowBal = IERC20(params.tokenBorrow).balanceOf(address(this));
        require(finalBorrowBal >= amountOwed, "FLASH: insufficient repay");

        IERC20(params.tokenBorrow).transfer(params.pair1, amountOwed);

        uint256 profit = finalBorrowBal - amountOwed;
        if (profit > 0) {
            IERC20(params.tokenBorrow).transfer(params.profitRecipient, profit);
        }

        emit FlashArbExecuted(
            tx.origin,
            params.pair1,
            params.tokenBorrow,
            params.amountBorrow,
            amountOwed,
            profit
        );
    }
}

